    record.pc = parse_u64(fields[3], line_number, "pc");
    record.micro_pc = parse_u64(fields[4], line_number, "micro_pc");
    record.seq_num = parse_u64(fields[5], line_number, "seq_num");
    record.disasm = std::string(line.substr(start));
