void convert(std::istream& input,
             EventStreamProto& output,
             const std::string& input_path,
             const std::string& tx_start_stage,
             const std::string& tx_end_stage)
{
    Definitions definitions{
        .start_transaction = output.define_event("start_transaction", "Beginning of a new transaction"),
        .end_transaction = output.define_event("end_transaction", "End of a transaction"),
        .txid = output.define_data("txid", "Transaction ID"),
        .seq_num = output.define_data("seq_num", "gem5 O3PipeView sequence number"),
        .pc = output.define_data("pc", "Instruction program counter"),
        .micro_pc = output.define_data("micro_pc", "Instruction micro-PC"),
        .disasm = output.define_data("disasm", "Instruction disassembly"),
    };

    std::vector<InstructionRecord> instructions;
    std::optional<InstructionRecord> current_instruction;

    std::size_t line_number = 0;
    std::string line;
    while (std::getline(input, line)) {
        ++line_number;

        if (!line.empty() && line.back() == '\r')
            line.pop_back();

        if (!line.starts_with("O3PipeView:"))
            continue;

        if (line.starts_with("O3PipeView:fetch:")) {
            if (current_instruction)
                parse_error(line_number, "encountered fetch before retire for the current instruction");
            current_instruction = parse_fetch_line(line, line_number);
            if (!definitions.stage_events.contains("fetch")) {
                definitions.stage_events.emplace("fetch",
                                                 output.define_event("fetch", "gem5 O3PipeView stage 'fetch'"));
            }
            continue;
        }

        if (!current_instruction)
            parse_error(line_number, "encountered stage before first fetch");

        parse_stage_line(line, line_number, *current_instruction, definitions, output);
        if (current_instruction->stage_times.contains("retire")) {
            instructions.push_back(std::move(*current_instruction));
            current_instruction.reset();
        }
    }

    if (input.bad())
        throw std::runtime_error("failed while reading input trace");
    if (current_instruction)
        throw std::runtime_error("input ended before retire for the current instruction");

    output.set_string_parameter("source_format", "Original trace format", "gem5.o3pipeview");
    output.set_string_parameter("time_unit", "Timestamp unit", "gem5_tick");
    output.set_string_parameter("tx_start_stage", "Stage used to emit start_transaction", tx_start_stage);
    output.set_string_parameter("tx_end_stage", "Stage used to emit end_transaction", tx_end_stage);
    if (input_path != "-")
        output.set_string_parameter("input_path", "Path to the source O3PipeView trace", input_path);
    output.start_simulation();

    for (const auto& instruction : instructions) {
        for (const auto& stage : instruction.stage_order) {
            auto time = instruction.stage_time(stage);
            if (!time || *time == 0)
                continue;

            if (stage == tx_start_stage)
                emit_marker(output, definitions.start_transaction, *time, definitions, instruction);

            emit_stage(output, definitions, instruction, stage, *time);

            if (stage == tx_end_stage)
                emit_marker(output, definitions.end_transaction, *time, definitions, instruction);
        }
    }
}

